const body = $input.first().json;
const { code, language, timeout, sandbox_mode } = body;

// 安全扫描：检测危险导入
const dangerous = ['os','sys','subprocess','socket','__import__','eval','exec'];
const detected = dangerous.filter(d => code.includes(d));

if (detected.length > 0) {
  throw new Error('DANGEROUS: Blocked imports detected: ' + detected.join(', '));
}

return [{json: {
  code,
  language: language || 'python',
  timeout: timeout || 30,
  sandbox_mode: sandbox_mode || 'docker',
  session_id: 'session_' + Date.now()
}}];
